WITH ranked AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY channel, promo_code ORDER BY starts_on, id) AS rank_in_group FROM promotions QUALIFY rank_in_group = 1) SELECT id, channel, promo_code, starts_on, ends_on, discount_pct, rank_in_group, CASE WHEN channel RLIKE '^(web|store)$' THEN 'GROUP_B' WHEN channel RLIKE '^(mobile|partner)$' THEN 'EXTENDED' ELSE 'OTHER_ZONE' END AS channel_zone FROM ranked ORDER BY starts_on NULLS LAST;
